package com.bank.merchant;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SmallestSaleDemo {
    private static final Logger log = Logger.getLogger(SmallestSaleDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        List<BigDecimal> sales = Arrays.asList(
            new BigDecimal("1500.00"),
            new BigDecimal("250.75"),
            new BigDecimal("9800.00"),
            new BigDecimal("640.00"));

        Account priya = new Account("CUR3001", "Priya Sharma", sales);
        SalesAnalyzer analyzer = new SalesAnalyzer();

        BigDecimal smallest = analyzer.findSmallestSale(priya.getAmounts());
        log.info(() -> "Smallest sale for " + priya.getHolderName()
                + " (" + priya.getAccountId() + ") = Rs." + smallest);
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
