package com.bank.merchant;

import java.math.BigDecimal;
import java.util.List;

class SalesAnalyzer {

    // O(n) scan: seed with first element, downgrade when a smaller one appears.
    BigDecimal findSmallestSale(List<BigDecimal> sales) {
        if (sales == null || sales.isEmpty()) {
            throw new IllegalArgumentException("No sales: smallest is undefined");
        }
        BigDecimal min = sales.get(0);            // assume first is smallest
        for (int i = 1; i < sales.size(); i++) {
            BigDecimal current = sales.get(i);
            if (current.compareTo(min) < 0) {     // found something smaller
                min = current;                    // downgrade the record holder
            }
        }
        return min;
    }
}
